17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Map;
20	import java.util.regex.Pattern;
21	
22	import org.springframework.samples.petclinic.util.LocalityResolver;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Validates an optional owner postcode against the region of the owner's city. When present a
27	 * postcode must be exactly four digits and, for a city whose region is known, fall within that
28	 * region's inclusive range. A city with no known region accepts any 4-digit postcode. An absent
29	 * (null) postcode is left unvalidated, keeping the create contract backward-compatible.
30	 */
31	@Component
32	public class PostcodeValidator {
33	
34	    /** A postcode must be exactly four digits. */
35	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
36	
37	    /** Region -> inclusive 4-digit postcode range {low, high}. */
38	    private static final Map<String, int[]> REGION_RANGE = Map.of(
39	        "NSW", new int[] {2000, 2099},
40	        "VIC", new int[] {3000, 3099},
41	        "QLD", new int[] {4000, 4099});
42	
43	    /**
44	     * @param postcode the raw submitted postcode (may be {@code null})
45	     * @param city the owner's city, used to resolve the region that fixes the valid range
46	     * @throws InvalidPostcodeException if the postcode is present but not four digits, or is out of
47	     *         range for the region of the given city
48	     */
49	    public void validate(String postcode, String city) {
50	        if (postcode == null) {
51	            return;
52	        }
53	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
54	            throw new InvalidPostcodeException("Postcode must be four digits, but was: " + postcode);
55	        }
56	        int[] range = REGION_RANGE.get(LocalityResolver.localityOf(city));
57	        if (range == null) {
58	            return;
59	        }
60	        int value = Integer.parseInt(postcode);
61	        if (value < range[0] || value > range[1]) {
62	            throw new InvalidPostcodeException(
63	                "Postcode " + postcode + " is out of range for city " + city);
64	        }
65	    }
66	}
