12	import org.springframework.samples.petclinic.util.LocalityResolver;
13	import org.springframework.samples.petclinic.util.MembershipLevelCalculator;
14	
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
25	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(computeMembershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
30	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
31	    @Mapping(target = "sharesHousehold", ignore = true)
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * Builds an owner's display name from the stored names, formatted as
36	     * {@code "LastName, FirstName"}.
37	     */
38	    default String formatDisplayName(Owner owner) {
39	        return owner.getLastName() + ", " + owner.getFirstName();
40	    }
41	
42	    /**
43	     * Builds an owner's initials from the stored names as the upper-cased first
44	     * letters of the first and last name, dot-separated with a trailing dot,
45	     * e.g. {@code "J.S."}.
46	     */
47	    default String formatInitials(Owner owner) {
48	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
49	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
50	    }
51	
52	    /**
53	     * Builds an owner's membership number from its stored fields, formatted
54	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of
55	     * the registration date's year, e.g. {@code "SMI-0007-M26"}. Returns
56	     * {@code null} when either the customer code or registration date is absent.
57	     */
58	    default String formatMembershipNumber(Owner owner) {
59	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
60	            return null;
61	        }
62	        return String.format("%s-M%02d", owner.getCustomerCode(),
63	            owner.getRegistrationDate().getYear() % 100);
64	    }
65	
66	    /**
67	     * Computes an owner's numeric membership level from its stored fields, delegating to
68	     * {@link MembershipLevelCalculator}.
69	     */
70	    default int computeMembershipLevel(Owner owner) {
71	        return MembershipLevelCalculator.levelOf(owner);
72	    }
73	
74	    /**
75	     * Derives an owner's locality (canonical region) from its stored city using the
76	     * fixed city-to-region table, yielding {@code "UNKNOWN"} for any unlisted city.
77	     */
78	    default String formatLocality(Owner owner) {
79	        return LocalityResolver.localityOf(owner.getCity());
80	    }
81	
82	    /**
83	     * Derives an owner's preferred contact channel from its stored fields:
84	     * {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}.
85	     */
86	    default String formatContactPreference(Owner owner) {
87	        return owner.hasEmail() ? "EMAIL" : "PHONE";
88	    }
89	
90	    /**
91	     * Derives an owner's identity key from its stored fields, delegating to {@link IdentityKey}.
92	     * This is the same key used to detect duplicate owners on create.
93	     */
94	    default String formatIdentityKey(Owner owner) {
95	        return IdentityKey.of(owner);
96	    }
97	
98	    Owner toOwner(OwnerDto ownerDto);
99	
100	    @Mapping(target = "id", ignore = true)
101	    @Mapping(target = "pets", ignore = true)
102	    @Mapping(target = "householdId", ignore = true)
103	    Owner toOwner(OwnerFieldsDto ownerDto);
104	
105	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
106	
107	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
108	
109	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
110	        OwnerPageDto ownerPageDto = new OwnerPageDto();
111	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
112	        ownerPageDto.setPage(ownerPage.getNumber());
113	        ownerPageDto.setSize(ownerPage.getSize());
114	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
115	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
116	        return ownerPageDto;
117	    }
118	}
